import{_ as e,o as a,c as r,a0 as i}from"./chunks/framework.CzVS_xMp.js";const d="/ai-data-center-systems/assets/roofline.D0yp4HQH.png",u=JSON.parse('{"title":"Week 2 — Hardware Foundations for Inference","description":"","frontmatter":{},"headers":[],"relativePath":"inference/efficient-llm-inference-systems/week02/index.md","filePath":"inference/efficient-llm-inference-systems/week02/index.md","lastUpdated":1788490169000}'),n={name:"inference/efficient-llm-inference-systems/week02/index.md"};function o(s,t,l,h,c,g){return a(),r("div",null,[...t[0]||(t[0]=[i('<h1 id="week-2-—-hardware-foundations-for-inference" tabindex="-1">Week 2 — Hardware Foundations for Inference <a class="header-anchor" href="#week-2-—-hardware-foundations-for-inference" aria-label="Permalink to &quot;Week 2 — Hardware Foundations for Inference&quot;">​</a></h1><blockquote><p>Pre-lab summary. Read this before running the hands-on exercises.</p></blockquote><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><p>All inference optimization is one principle in disguise: <strong>keep data in the fastest memory you can, and minimize traffic to slower memory.</strong> Once you internalize the GPU memory hierarchy in numbers, every technique in the rest of the course (FlashAttention, kernel fusion, KV cache, paging, quantization, tensor parallelism, disaggregated serving) collapses into the same logic — just applied to different layers of that hierarchy.</p><h2 id="_1-gpu-memory-hierarchy-h100-sxm5" tabindex="-1">1. GPU Memory Hierarchy (H100 SXM5) <a class="header-anchor" href="#_1-gpu-memory-hierarchy-h100-sxm5" aria-label="Permalink to &quot;1. GPU Memory Hierarchy (H100 SXM5)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Level</th><th>Capacity</th><th>Bandwidth</th><th>Latency</th><th>Controlled by</th></tr></thead><tbody><tr><td>Registers</td><td>~256 KB / SM</td><td>&gt;20 TB/s</td><td>~1 cycle</td><td>compiler</td></tr><tr><td>Shared memory (L1)</td><td>228 KB / SM</td><td>~10 TB/s</td><td>~20 cycles</td><td>kernel author</td></tr><tr><td>L2 cache</td><td>50 MB</td><td>~12 TB/s</td><td>~150 cycles</td><td>hardware</td></tr><tr><td>HBM3</td><td>80 GB</td><td>3.35 TB/s</td><td>~600 cycles</td><td>hardware (on miss)</td></tr><tr><td>NVLink 4 (cross-GPU)</td><td>—</td><td>900 GB/s bidi</td><td>μs</td><td>NCCL</td></tr><tr><td>PCIe gen5 (host)</td><td>—</td><td>128 GB/s bidi</td><td>μs</td><td>driver</td></tr></tbody></table><p><strong>Mental model:</strong> every order-of-magnitude drop in bandwidth is also an order-of-magnitude jump in latency. Optimization = find the layer where you&#39;re spending traffic and push it down to a faster layer.</p><h2 id="_2-every-optimization-mapped-to-the-hierarchy" tabindex="-1">2. Every Optimization, Mapped to the Hierarchy <a class="header-anchor" href="#_2-every-optimization-mapped-to-the-hierarchy" aria-label="Permalink to &quot;2. Every Optimization, Mapped to the Hierarchy&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Technique</th><th>Traffic it removes</th></tr></thead><tbody><tr><td>FlashAttention</td><td>n×n attention matrix → keep tiles in SRAM instead of HBM</td></tr><tr><td>Kernel fusion</td><td>intermediate tensors → registers/shared mem instead of HBM round-trip</td></tr><tr><td>KV cache</td><td>recomputing K,V from scratch → read once from HBM</td></tr><tr><td>Quantization (W4/W8)</td><td>fewer bytes per weight load from HBM</td></tr><tr><td>PagedAttention</td><td>KV fragmentation waste in HBM</td></tr><tr><td>Tensor parallelism</td><td>single-HBM capacity wall → spread across NVLink</td></tr><tr><td>Disaggregated serving</td><td>prefill choking decode in shared HBM → physical separation</td></tr></tbody></table><p>Different layer, same idea.</p><h2 id="_3-tensor-cores-and-precision" tabindex="-1">3. Tensor Cores and Precision <a class="header-anchor" href="#_3-tensor-cores-and-precision" aria-label="Permalink to &quot;3. Tensor Cores and Precision&quot;">​</a></h2><p>H100 SXM Tensor Core peak by format:</p><table tabindex="0"><thead><tr><th>Format</th><th style="text-align:right;">Dense peak</th><th style="text-align:right;">Sparse peak</th><th>Notes</th></tr></thead><tbody><tr><td>BF16 / FP16</td><td style="text-align:right;">~990 TFLOPS</td><td style="text-align:right;">1,979 TFLOPS</td><td>inference baseline</td></tr><tr><td>FP8 (E4M3)</td><td style="text-align:right;">1,979 TFLOPS</td><td style="text-align:right;">3,958 TFLOPS</td><td>exactly 2x BF16/FP16</td></tr><tr><td>INT8</td><td style="text-align:right;">1,979 TOPS</td><td style="text-align:right;">3,958 TOPS</td><td>same throughput as FP8</td></tr><tr><td>FP4</td><td style="text-align:right;">none</td><td style="text-align:right;">none</td><td>B200 adds FP4</td></tr></tbody></table><p>Source: <a href="https://www.nvidia.com/en-us/data-center/h100/" target="_blank" rel="noreferrer">NVIDIA H100 product specifications</a> list the H100 SXM Tensor Core figures with sparsity; the dense values are half of those sparse peaks.</p><p><strong>Why exactly 2×:</strong> Tensor Cores process fixed-size tiles. Halve the bit-width, fit twice as many elements in the same silicon area.</p><p><strong>Operational implication:</strong></p><ul><li>Decode is memory-bound → quantize <strong>weights</strong> (W4A16) to cut bandwidth.</li><li>Prefill is compute-bound → quantize <strong>compute</strong> (W8A8 / FP8) to use the faster Tensor Core path.</li><li>A serving system can mix both regimes (see disaggregation in Week 8).</li></ul><p><strong>FP8 vs INT8</strong> (same throughput, different properties):</p><table tabindex="0"><thead><tr><th></th><th>INT8</th><th>FP8 (E4M3)</th></tr></thead><tbody><tr><td>Range</td><td>-128 to 127</td><td>±448</td></tr><tr><td>Distribution</td><td>uniform</td><td>exponential, dense near zero</td></tr><tr><td>Outlier handling</td><td>hard (needs SmoothQuant etc.)</td><td>natural</td></tr><tr><td>Per-channel scaling</td><td>usually required</td><td>usually not</td></tr></tbody></table><p>If you&#39;re on H100+, default to FP8. INT8 is for Ampere and earlier.</p><h2 id="_4-h100-→-b200-shift-matters-for-cluster-planning" tabindex="-1">4. H100 → B200 Shift (matters for cluster planning) <a class="header-anchor" href="#_4-h100-→-b200-shift-matters-for-cluster-planning" aria-label="Permalink to &quot;4. H100 → B200 Shift (matters for cluster planning)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Dim</th><th>H100 SXM</th><th>B200 SXM</th><th>What it changes</th></tr></thead><tbody><tr><td>HBM</td><td>80 GB @ 3.35 TB/s</td><td>180 GB @ 8 TB/s</td><td>decode ~2.4× faster</td></tr><tr><td>FP8 TFLOPS (dense / sparse)</td><td>1,979 / 3,958</td><td>4,500 / 9,000</td><td>prefill compute ~2.3× faster</td></tr><tr><td>FP4 TFLOPS (dense / sparse)</td><td>none</td><td>9,000 / 18,000</td><td>new quantization frontier</td></tr><tr><td>NVLink</td><td>gen 4, 900 GB/s</td><td>gen 5, 1,800 GB/s</td><td>TP scaling further</td></tr></tbody></table><p>Bandwidth grew <strong>more than</strong> compute. This means <strong>decode-heavy workloads benefit disproportionately on B200</strong>. For prefill-heavy mixes, the gap is smaller. This is the exact technical reason mixed-generation clusters (H100 prefill nodes + B200 decode nodes) start to make economic sense.</p><p>Sources: <a href="https://www.nvidia.com/en-us/data-center/h100/" target="_blank" rel="noreferrer">NVIDIA H100 product specifications</a> and <a href="https://www.nvidia.com/en-us/data-center/dgx-b200/" target="_blank" rel="noreferrer">NVIDIA DGX B200 specifications</a>. DGX B200 lists 72 PFLOPS FP8 Tensor Core sparse performance for 8 GPUs; dense performance is half, so per-GPU FP8 is 4.5 PFLOPS dense / 9 PFLOPS sparse.</p><h2 id="_5-gemm-vs-gemv-—-reading-last-week-s-numbers-through-hardware" tabindex="-1">5. GEMM vs GEMV — Reading Last Week&#39;s Numbers Through Hardware <a class="header-anchor" href="#_5-gemm-vs-gemv-—-reading-last-week-s-numbers-through-hardware" aria-label="Permalink to &quot;5. GEMM vs GEMV — Reading Last Week&#39;s Numbers Through Hardware&quot;">​</a></h2><p>Last week&#39;s batch sweep on a 3B model in 16 GB VRAM showed throughput-scaling efficiency dropping to ~47% at batch 128. Why?</p><p><strong>Prefill (GEMM, compute-bound).</strong> A 3B model is too small to saturate H100&#39;s tensor cores — tile sizes don&#39;t fill, kernel-launch overhead is relatively large, FlashAttention efficiency degrades on small models. End-to-end MFU ends up around 2–5%. A 70B model on the same hardware would hit 30–50% MFU, because the work-per-launch ratio is much higher.</p><p><strong>Decode (GEMV, memory-bound).</strong> Theoretical step time for a 3B BF16 model on H100: 6 GB / 3.35 TB/s ≈ 1.79 ms. Measured: ~12 ms. The gap is framework overhead — Python, sampler, kernel launches — which doesn&#39;t scale with model size. On a 70B model the same overhead becomes negligible noise.</p><p><strong>Takeaway:</strong> small models on big GPUs are an inefficient match. RTX 4090 / L4 / Jetson are often the right target for ≤ 7B; H100/B200 only earn their cost on ≥ 30B or high-concurrency batched serving.</p><h2 id="_6-nvlink-and-tensor-parallelism-communication-math" tabindex="-1">6. NVLink and Tensor Parallelism Communication Math <a class="header-anchor" href="#_6-nvlink-and-tensor-parallelism-communication-math" aria-label="Permalink to &quot;6. NVLink and Tensor Parallelism Communication Math&quot;">​</a></h2><p>TP across N GPUs requires <strong>two AllReduces per transformer layer</strong> (one after attention output projection, one after FFN down projection).</p><p>Per-AllReduce traffic (BF16): <code>2 × batch × seq_len × d_model</code> bytes.</p><p><strong>Worked example — 70B (d_model=8192), batch=32, seq=2048, BF16:</strong></p><ul><li>Per-AllReduce: 2.15 GB</li><li>80 layers × 2 AllReduces = 344 GB per forward pass</li><li>H100 NVLink-4 8-way ring, ~750 GB/s effective: ~460 ms communication</li></ul><p>That&#39;s the same order of magnitude as compute — meaning communication is a real cost, not noise. It also means:</p><table tabindex="0"><thead><tr><th>Model</th><th>Practical parallelism</th></tr></thead><tbody><tr><td>≤ 7B</td><td>TP=1, scale via DP</td></tr><tr><td>13–30B</td><td>TP=2–4 inside NVLink</td></tr><tr><td>70B</td><td>TP=8 single-node NVLink</td></tr><tr><td>175B+</td><td>TP=8 + PP across nodes (PP only sends activations — InfiniBand is fine)</td></tr><tr><td>405B+</td><td>TP=8 + PP + DP, or expert parallelism for MoE</td></tr></tbody></table><p><strong>Rule of thumb:</strong> TP stays inside NVLink/NVSwitch. PP can cross InfiniBand. DP goes anywhere.</p><h2 id="_7-heterogeneous-hardware" tabindex="-1">7. Heterogeneous Hardware <a class="header-anchor" href="#_7-heterogeneous-hardware" aria-label="Permalink to &quot;7. Heterogeneous Hardware&quot;">​</a></h2><h3 id="apple-silicon-—-capacity-beats-bandwidth-sometimes" tabindex="-1">Apple Silicon — capacity beats bandwidth (sometimes) <a class="header-anchor" href="#apple-silicon-—-capacity-beats-bandwidth-sometimes" aria-label="Permalink to &quot;Apple Silicon — capacity beats bandwidth (sometimes)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Dim</th><th>A100 80GB</th><th>M3 Ultra 192GB</th></tr></thead><tbody><tr><td>Memory</td><td>80 GB HBM</td><td>192 GB unified</td></tr><tr><td>Bandwidth</td><td>2 TB/s</td><td>800 GB/s</td></tr><tr><td>FP16 TFLOPS</td><td>312</td><td>28</td></tr><tr><td>70B BF16 (140 GB)</td><td>won&#39;t fit</td><td>fits comfortably</td></tr></tbody></table><p>H100 can&#39;t hold a 70B BF16 model alone; M3 Ultra can, and gets ~30 tok/s. For decode-bound workloads, <strong>fitting</strong> can matter more than peak FLOPS. Useful for dev laptops, on-prem demos, edge prototypes.</p><h3 id="jetson-orin-—-the-edge-inference-reality-check" tabindex="-1">Jetson Orin — the edge inference reality check <a class="header-anchor" href="#jetson-orin-—-the-edge-inference-reality-check" aria-label="Permalink to &quot;Jetson Orin — the edge inference reality check&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Model</th><th>FP16 TFLOPS</th><th>Memory</th><th>Bandwidth</th><th>TDP</th></tr></thead><tbody><tr><td>Orin Nano 8GB</td><td>20</td><td>8 GB LPDDR5</td><td>68 GB/s</td><td>7–15 W</td></tr><tr><td>Orin NX 16GB</td><td>50</td><td>16 GB LPDDR5</td><td>102 GB/s</td><td>10–25 W</td></tr><tr><td>AGX Orin 64GB</td><td>138</td><td>64 GB LPDDR5</td><td>204 GB/s</td><td>15–60 W</td></tr><tr><td>Thor (2025+)</td><td>~700 (FP4)</td><td>128 GB</td><td>~273 GB/s</td><td>40–130 W</td></tr></tbody></table><p>For reference: H100 SXM5 = 1,979 FP16 TFLOPS, 3.35 TB/s, 700 W.</p><p>AGX Orin is roughly 14× slower than H100 in FP16 and 16× lower in bandwidth — but ~15× cheaper and ~12× lower TDP. Per-dollar and per-watt, Orin can win, <strong>but only if the model is small enough</strong> (≤ 3B comfortably, 7B with INT4).</p><h3 id="specialty-silicon-know-of-not-deploy-now" tabindex="-1">Specialty silicon (know-of, not deploy-now) <a class="header-anchor" href="#specialty-silicon-know-of-not-deploy-now" aria-label="Permalink to &quot;Specialty silicon (know-of, not deploy-now)&quot;">​</a></h3><ul><li><strong>Groq LPU</strong> — SRAM-only, deterministic single-stream latency. No batching → low concurrency. Wins on hard-latency, low-QPS scenarios.</li><li><strong>Cerebras WSE-3</strong> — wafer-scale, 44 GB on-chip SRAM. If your model fits, the HBM bottleneck simply doesn&#39;t exist.</li></ul><p>These exist as motivations: they answer &quot;what would inference look like if we removed the HBM bottleneck entirely?&quot;</p><h2 id="_8-what-to-do-with-this-before-the-lab" tabindex="-1">8. What to Do With This Before the Lab <a class="header-anchor" href="#_8-what-to-do-with-this-before-the-lab" aria-label="Permalink to &quot;8. What to Do With This Before the Lab&quot;">​</a></h2><p>Before running the hands-on exercises, make sure you can answer:</p><ul><li>For any given GPU + model size + precision, can I estimate decode step latency in 30 seconds on a napkin?</li><li>Why is <code>nvidia-smi</code>&#39;s GPU-Util misleading for memory-bound decode? What should I look at instead?</li><li>At what TP degree does NVLink communication become a meaningful fraction of forward-pass time?</li><li>Where is the cost-efficient hardware target for a 3B model? A 70B model? A 405B model?</li></ul><p>If any of these are still fuzzy, re-read the relevant section above. The exercises will only land if the mental model is in place first.</p><h2 id="_9-lab-preview" tabindex="-1">9. Lab Preview <a class="header-anchor" href="#_9-lab-preview" aria-label="Permalink to &quot;9. Lab Preview&quot;">​</a></h2><p>Three exercises in increasing return on time:</p><ol><li><strong>Roofline plot</strong> (highest ROI, ~1 hour) — measure GEMM/GEMV across shapes, plot achieved TFLOPS vs arithmetic intensity. The roofline emerges from your own data.</li><li><strong>NCU on attention kernel</strong> (~1 hour) — read actual achieved HBM bandwidth from Nsight Compute. Compare to what <code>nvidia-smi</code> says. Don&#39;t trust GPU-Util again.</li><li><strong>NVLink AllReduce sweep</strong> (multi-GPU only) — measure effective bandwidth as a function of message size; find the latency-vs-bandwidth knee.</li></ol><p>Start with #1.</p><h2 id="recommended-reading" tabindex="-1">Recommended Reading <a class="header-anchor" href="#recommended-reading" aria-label="Permalink to &quot;Recommended Reading&quot;">​</a></h2><ul><li><a href="https://resources.nvidia.com/en-us-hopper-architecture/nvidia-h100-tensor-c" target="_blank" rel="noreferrer">NVIDIA H100 Tensor Core GPU Architecture</a> (2022) — Describes HBM, Tensor Core, NVLink, and Hopper&#39;s inference-related hardware features.</li></ul><hr><h1 id="lab-results" tabindex="-1">Lab Results <a class="header-anchor" href="#lab-results" aria-label="Permalink to &quot;Lab Results&quot;">​</a></h1><blockquote><p>Measurements done on RTX 5080 (Blackwell, CC 12.0, 16 GB GDDR7, ~960 GB/s, ~113 TFLOPS dense BF16 with FP32 accumulate) with Qwen2.5-3B-Instruct in BF16, varying batch and sequence length. Three exercises were run; NVLink sweep was skipped (single-GPU). Sources: <a href="https://www.nvidia.com/en-us/geforce/graphics-cards/50-series/rtx-5080/" target="_blank" rel="noreferrer">NVIDIA RTX 5080 specifications</a> and <a href="https://images.nvidia.com/aem-dam/Solutions/geforce/blackwell/nvidia-rtx-blackwell-gpu-architecture.pdf" target="_blank" rel="noreferrer">NVIDIA RTX Blackwell GPU architecture</a>.</p></blockquote><h2 id="headline-findings" tabindex="-1">Headline Findings <a class="header-anchor" href="#headline-findings" aria-label="Permalink to &quot;Headline Findings&quot;">​</a></h2><ol><li><strong><code>nvidia-smi</code> GPU-Util is misleading.</strong> At batch=1, GPU-Util reads 89% while NCU shows the attention kernel is using 1.13% of SM throughput and 1.75% of DRAM throughput. The kernel is <strong>launch-overhead-bound</strong>, not memory-bound. GPU-Util only measures &quot;is any kernel running,&quot; not &quot;is anything productive happening.&quot;</li><li><strong>The cuBLAS kernel path changes between batch=16 and batch=32.</strong> At batch=1, FFN matmuls dispatch to CUDA-Core GEMV (<code>gemvx</code>, 66% of CUDA time). At batch=32, they dispatch to Tensor-Core GEMM (<code>cutlass_..._tensorop_bf16</code>, 81% of CUDA time). This is not a gradual transition — it is cuBLAS choosing a different algorithm because Tensor Core tiles (16×16) only fill efficiently from M=16+.</li><li><strong>The textbook claim &quot;decode = memory-bound&quot; needs qualification.</strong> What we actually see is a four-stage transition: <ul><li>tiny batch + short seq → <strong>launch-overhead-bound</strong></li><li>small batch + long seq → <strong>L2 → HBM transition</strong></li><li>medium batch (16–64) → <strong>HBM-bandwidth-bound</strong> (the textbook regime)</li><li>large batch (128+) → <strong>compute-bound</strong> (Tensor Cores)</li></ul></li><li><strong>Ridge point on this hardware is around AI ≈ 120 FLOP/byte, not the spec&#39;s 234.</strong> The 234 figure assumed the sparse BF16 Tensor Core peak (225.1 TFLOPS). Dense BF16 with FP32 accumulate on RTX 5080 is 112.6 TFLOPS, putting the real ridge at 112.6 / 0.96 ≈ 117 FLOP/byte. Measurements deviate from the memory-ceiling at exactly M=128 (AI=119), confirming the dense peak.</li></ol><h2 id="lab-1a-—-kernel-inventory-probe-kernels-py" tabindex="-1">Lab 1a — Kernel Inventory (<code>probe_kernels.py</code>) <a class="header-anchor" href="#lab-1a-—-kernel-inventory-probe-kernels-py" aria-label="Permalink to &quot;Lab 1a — Kernel Inventory (`probe_kernels.py`)&quot;">​</a></h2><p>CUDA time distribution from <code>torch.profiler</code> over a few decode steps. Two snapshots, batch=1 and batch=32:</p><table tabindex="0"><thead><tr><th></th><th>Batch=1</th><th>Batch=32</th></tr></thead><tbody><tr><td>Top kernel</td><td><code>gemvx</code> BF16 GEMV (47.2%, 725 calls)</td><td><code>cutlass_..._tensorop_bf16</code> GEMM (34.4%, 432 calls)</td></tr><tr><td>#2</td><td><code>gemvx</code> BF16 GEMV (19.3%, 540 calls)</td><td><code>cutlass_..._tensorop_bf16</code> GEMM (23.1%, 433 calls)</td></tr><tr><td>#3</td><td><code>cutlass_..._wmma</code> GEMM (14.3%, 181 calls)</td><td><code>cutlass_..._tensorop_bf16</code> GEMM (15.2%, 432 calls)</td></tr><tr><td>Tensor-Core share of CUDA time</td><td>~14%</td><td>~81%</td></tr><tr><td>CUDA-Core GEMV share</td><td>~66%</td><td>~0% (gone)</td></tr><tr><td>FlashAttention share</td><td>1.7% (decode) + 0.5% (prefill)</td><td>1.2% (decode) + 2.2% (prefill)</td></tr></tbody></table><p><strong>Reading.</strong> The 432-call clusters at batch=32 are the three FFN linear layers (<code>gate_proj</code>, <code>up_proj</code>, <code>down_proj</code>) of Qwen2.5&#39;s SwiGLU FFN, called once per layer per decode step. At batch=1 these collapse into GEMV calls on CUDA cores; at batch=32 they become Tensor-Core GEMMs because M=32 fills enough of a 16×16 Tensor-Core tile.</p><p>Attention is never the bottleneck in this setup. KV-cache optimizations (GQA, MLA, paging) save <strong>memory</strong>, not decode latency on this kind of workload.</p><h2 id="lab-1b-—-ncu-speed-of-light-decode-steps-under-cudaprofilerstart" tabindex="-1">Lab 1b — NCU Speed-of-Light (decode steps under <code>cudaProfilerStart</code>) <a class="header-anchor" href="#lab-1b-—-ncu-speed-of-light-decode-steps-under-cudaprofilerstart" aria-label="Permalink to &quot;Lab 1b — NCU Speed-of-Light (decode steps under `cudaProfilerStart`)&quot;">​</a></h2><p>The flash_fwd_kernel under NCU at two batch sizes:</p><table tabindex="0"><thead><tr><th>Metric</th><th>Batch=1</th><th>Batch=32</th><th>Multiplier</th></tr></thead><tbody><tr><td>SM Busy</td><td>1.13%</td><td>31.5%</td><td>28×</td></tr><tr><td>DRAM Throughput (% of peak)</td><td>1.75%</td><td>8.5%</td><td>4.9×</td></tr><tr><td>Memory Throughput (GB/s)</td><td>16.5</td><td>80.2</td><td>4.9×</td></tr><tr><td>SM Active Cycles</td><td>340</td><td>10,961</td><td>32×</td></tr><tr><td>Elapsed Cycles</td><td>17,643</td><td>20,389</td><td>1.16×</td></tr><tr><td>Duration (μs)</td><td>6.78</td><td>7.90</td><td>1.16×</td></tr><tr><td>L2 Hit Rate</td><td>77.6%</td><td>36.9%</td><td>0.5×</td></tr></tbody></table><p><strong>Reading.</strong> This is one of the cleanest demonstrations of batching&#39;s mechanism we&#39;ll see in the course. Going from batch=1 to batch=32:</p><ul><li>Work scales 32×: SM Active Cycles 340 → 10,961.</li><li>Wall-clock scales only 1.16×: Duration 6.78 → 7.90 μs.</li><li>The fixed cost (kernel launch + teardown, roughly 17,000 cycles) was already there at batch=1; batching just added compute on top of it.</li><li>L2 hit rate halving is the signal that KV cache no longer fits in L2 (small KV at batch=1 fits in 64 MB L2; at batch=32, ~24 MB of KV pushes some traffic to HBM).</li></ul><p>Translation: at batch=1 the attention kernel is 98% idle (340 / 17,643 SM-active fraction). At batch=32 it is doing real work for ~54% of its wall-clock duration. That gap is exactly what continuous batching exploits.</p><h2 id="lab-2-—-roofline-roofline-benchmark-py-ffn-gate-up-shape-k-2048-n-11008" tabindex="-1">Lab 2 — Roofline (<code>roofline_benchmark.py</code>, FFN gate/up shape: K=2048, N=11008) <a class="header-anchor" href="#lab-2-—-roofline-roofline-benchmark-py-ffn-gate-up-shape-k-2048-n-11008" aria-label="Permalink to &quot;Lab 2 — Roofline (`roofline_benchmark.py`, FFN gate/up shape: K=2048, N=11008)&quot;">​</a></h2><p><img src="'+d+'" alt="Roofline"></p><p>Methodology:</p><ul><li>Timing uses CUDA events around repeated PyTorch BF16 matmul loops, reported as the median of 5 repeats × 200 iterations after warmup.</li><li>Wall-clock time is also recorded by the script, but TFLOPS and roofline placement use GPU event time.</li><li><code>Effective GB/s</code> is computed analytically from BF16 tensor sizes (<code>A</code>, <code>B</code>, <code>C</code>), not from hardware DRAM counters. Values above 960 GB/s are expected when L2/cache reuse serves part of the traffic.</li><li>Peak references are RTX 5080 BF16 Tensor Core dense with FP32 accumulate = 112.6 TFLOPS, sparse spec = 225.1 TFLOPS, memory bandwidth = 960 GB/s.</li></ul><p>Raw measurements from <code>roofline_data.json</code>:</p><table tabindex="0"><thead><tr><th>M</th><th style="text-align:right;">GPU time (μs)</th><th style="text-align:right;">Wall time (μs)</th><th style="text-align:right;">TFLOPS</th><th style="text-align:right;">%dense peak</th><th style="text-align:right;">Effective GB/s</th><th style="text-align:right;">%mem peak</th><th style="text-align:right;">AI (FLOP/byte)</th></tr></thead><tbody><tr><td>1</td><td style="text-align:right;">68.7</td><td style="text-align:right;">68.8</td><td style="text-align:right;">0.7</td><td style="text-align:right;">0.6%</td><td style="text-align:right;">656</td><td style="text-align:right;">68%</td><td style="text-align:right;">1.0</td></tr><tr><td>2</td><td style="text-align:right;">39.5</td><td style="text-align:right;">39.6</td><td style="text-align:right;">2.3</td><td style="text-align:right;">2.0%</td><td style="text-align:right;">1,142</td><td style="text-align:right;">119%</td><td style="text-align:right;">2.0</td></tr><tr><td>4</td><td style="text-align:right;">39.6</td><td style="text-align:right;">39.8</td><td style="text-align:right;">4.6</td><td style="text-align:right;">4.0%</td><td style="text-align:right;">1,142</td><td style="text-align:right;">119%</td><td style="text-align:right;">4.0</td></tr><tr><td>8</td><td style="text-align:right;">40.9</td><td style="text-align:right;">40.9</td><td style="text-align:right;">8.8</td><td style="text-align:right;">7.8%</td><td style="text-align:right;">1,108</td><td style="text-align:right;">115%</td><td style="text-align:right;">8.0</td></tr><tr><td>16</td><td style="text-align:right;">43.3</td><td style="text-align:right;">44.0</td><td style="text-align:right;">16.7</td><td style="text-align:right;">14.8%</td><td style="text-align:right;">1,052</td><td style="text-align:right;">110%</td><td style="text-align:right;">15.9</td></tr><tr><td>32</td><td style="text-align:right;">36.0</td><td style="text-align:right;">36.1</td><td style="text-align:right;">40.0</td><td style="text-align:right;">35.6%</td><td style="text-align:right;">1,274</td><td style="text-align:right;">133%</td><td style="text-align:right;">31.4</td></tr><tr><td><strong>64</strong></td><td style="text-align:right;"><strong>36.6</strong></td><td style="text-align:right;"><strong>37.1</strong></td><td style="text-align:right;"><strong>78.8</strong></td><td style="text-align:right;"><strong>70.0%</strong></td><td style="text-align:right;"><strong>1,276</strong></td><td style="text-align:right;"><strong>133%</strong></td><td style="text-align:right;"><strong>61.7</strong></td></tr><tr><td>128</td><td style="text-align:right;">66.0</td><td style="text-align:right;">67.1</td><td style="text-align:right;">87.5</td><td style="text-align:right;">77.7%</td><td style="text-align:right;">734</td><td style="text-align:right;">76%</td><td style="text-align:right;">119.2</td></tr><tr><td>256</td><td style="text-align:right;">123.0</td><td style="text-align:right;">123.5</td><td style="text-align:right;">93.9</td><td style="text-align:right;">83.4%</td><td style="text-align:right;">421</td><td style="text-align:right;">44%</td><td style="text-align:right;">222.9</td></tr><tr><td>512</td><td style="text-align:right;">233.1</td><td style="text-align:right;">233.6</td><td style="text-align:right;">99.0</td><td style="text-align:right;">88.0%</td><td style="text-align:right;">251</td><td style="text-align:right;">26%</td><td style="text-align:right;">394.9</td></tr><tr><td>1024</td><td style="text-align:right;">454.8</td><td style="text-align:right;">454.9</td><td style="text-align:right;">101.5</td><td style="text-align:right;">90.2%</td><td style="text-align:right;">158</td><td style="text-align:right;">16%</td><td style="text-align:right;">642.8</td></tr><tr><td>2048</td><td style="text-align:right;">927.4</td><td style="text-align:right;">928.8</td><td style="text-align:right;">99.6</td><td style="text-align:right;">88.4%</td><td style="text-align:right;">106</td><td style="text-align:right;">11%</td><td style="text-align:right;">936.9</td></tr></tbody></table><p><strong>Reading.</strong></p><ul><li><strong>The plateau lands at ~100–102 TFLOPS, not 225.1 TFLOPS.</strong> This rules out the sparse peak and confirms ~113 TFLOPS dense as the real BF16 ceiling for this PyTorch BF16 matmul. M=1024 hits 90.2% of dense peak, which is excellent for a generic PyTorch matmul.</li><li><strong>Apparent bandwidth above peak (M=2 through M=64 reading 110–133% of 960 GB/s) is cache/reuse, not impossible HBM bandwidth.</strong> <code>Effective GB/s</code> is computed from tensor sizes; in reality some of those bytes are served from L2 or reused within the GEMM kernel. NCU&#39;s <code>dram__bytes_read.sum</code> gives the true HBM number — that one stays under peak.</li><li><strong>M=64 is the per-matmul efficiency sweet spot on this hardware</strong> (highest combined memory + compute utilization). This matches Week 1&#39;s batch sweep, where batch=64 had the best balance of TPOT (19.4 ms) and throughput (3,297 tok/s) before efficiency collapsed at batch=128.</li><li><strong>The measured ridge sits around AI ≈ 120,</strong> matching dense-peak / bandwidth = 112.6 / 0.96 ≈ 117. M=128 (AI=119) is the first point clearly off the memory-ceiling line; M=256+ is unambiguously on the compute ceiling.</li></ul><h2 id="cross-references-between-labs" tabindex="-1">Cross-References Between Labs <a class="header-anchor" href="#cross-references-between-labs" aria-label="Permalink to &quot;Cross-References Between Labs&quot;">​</a></h2><p>The three labs corroborate each other:</p><table tabindex="0"><thead><tr><th>Observation</th><th>Lab 1a (probe)</th><th>Lab 1b (NCU)</th><th>Lab 2 (roofline)</th></tr></thead><tbody><tr><td>Batch=1 is launch-bound</td><td>GEMV dispatched (low arithmetic intensity)</td><td>SM Busy 1.13%, DRAM 1.75%</td><td>M=1 below memory ceiling</td></tr><tr><td>Tensor-Core path activates around M=16–32</td><td><code>gemvx</code> → <code>cutlass_tensorop</code> switch</td><td>SM Busy 1.13% → 31.5%</td><td>TFLOPS ramp from 16 → 35 → 75</td></tr><tr><td>Memory-bound regime occupies M=2–64</td><td>GEMV dominates at b=1; small GEMM at b=32</td><td>DRAM utilization rising</td><td>Points sit on the memory ceiling line</td></tr><tr><td>Ridge near AI=120</td><td>(n/a — measured by Lab 2)</td><td>(n/a)</td><td>Direct measurement: M=128 inflection</td></tr><tr><td>Compute ceiling ≈ 100 TFLOPS</td><td>(n/a)</td><td>(n/a)</td><td>M=1024 plateau at 101.5 TFLOPS</td></tr></tbody></table><h2 id="what-this-calibrates-going-forward" tabindex="-1">What This Calibrates Going Forward <a class="header-anchor" href="#what-this-calibrates-going-forward" aria-label="Permalink to &quot;What This Calibrates Going Forward&quot;">​</a></h2><p>Concretely, this set of measurements gives operating numbers for the rest of the course:</p><ul><li><strong>Operating batch sweet spot for Qwen2.5-3B BF16 on RTX 5080: 64.</strong> Latency stays acceptable (TPOT 19 ms), throughput is 40× the batch=1 baseline, and per-matmul efficiency is at its peak (~70% of dense BF16 ceiling). Pushing to 128 buys throughput at a steep latency cost; beyond 128, ridge point is hit and additional batch buys little.</li><li><strong>L2/cache effects matter at small batch / short sequence.</strong> Any benchmark that reports &gt;100% effective HBM peak bandwidth is not lying about throughput — it is using an analytic byte count, while the kernel is getting some data from cache or reuse. NCU&#39;s <code>dram__bytes_read.sum</code> is the right metric to isolate true HBM traffic.</li><li><strong>Decode-latency optimization on this kind of workload should target FFN GEMM/GEMV, not attention.</strong> Attention kernels are ❤️% of CUDA time. Quantizing FFN weights (W4A16) saves bytes-loaded on the actual hot path; KV-cache compression saves memory but not latency.</li><li><strong><code>nvidia-smi</code> GPU-Util is permanently retired as a diagnostic metric</strong> for this course. Use NCU SOL throughputs (<code>sm__throughput.avg.pct_of_peak_sustained_elapsed</code>, <code>dram__throughput.avg.pct_of_peak_sustained_elapsed</code>) instead.</li></ul><h2 id="lab-3-—-nvlink-sweep" tabindex="-1">Lab 3 — NVLink Sweep <a class="header-anchor" href="#lab-3-—-nvlink-sweep" aria-label="Permalink to &quot;Lab 3 — NVLink Sweep&quot;">​</a></h2><p>Skipped: single-GPU homelab. Will revisit when running on a multi-GPU node where TP communication actually exists. The numerical model in §6 of this README still applies — the AllReduce volume calculation does not need the hardware to be sound.</p>',90)])])}const m=e(n,[["render",o]]);export{u as __pageData,m as default};
